n *\n * 关键：**0.1.5 / 0.1.6 同时具备两套接口**，只看「接口存不存在」会把它们误判成新版 —— 而那一代\n * 还没有把 loader 行的 Config 注册成 settings 命名空间，于是 `describe()` 永远看不到我们（读恒空）、\n * `update()` 抛 `settings namespace \"…\" is not registered`（写必失败），表现为「连接列表永远是空的、\n * 导入与保存都没反应」。所以两套都在时，只有当 `describe()` **真的能看到本插件命名空间**才走新路径。\n */\nfunction settingsApiMode(svc, entryId) {\n  const canDescribe = !!svc && typeof svc.describe === \"function\" && typeof svc.update === \"function\";\n  const canRegister = !!svc && typeof svc.register === \"function\";\n  if (!canDescribe) return canRegister ? \"legacy\" : \"config\";\n  if (!canRegister) return \"new\";\n  try {\n    const list = svc.describe({ redactSecrets: false }) || [];\n    if (list.some((d) => d && String(d.ns) === String(entryId))) return \"new\";\n  } catch (e) {}\n  return \"legacy\";\n}\n\nfunction createNewSettingsFace(svc, entryId, rawConfig, log, migrated, homeDir) {\n  const warn = function (msg) { try { if (log && typeof log.warn === \"function\") log.warn(msg); } catch (e) {} };\n  const formOf = function () {\n    try {\n      // 密码认证必须在运行时拿到明文口令（sshArgv 要拼进子进程），脱敏移到 API 边界\n      // （publicProfiles）而不是在这里读回空值 —— 那会让所有密码连接在所有平台上静默失效。\n      return (svc.describe({ redactSecrets: false }) || []).find((d) => d && d.ns === entryId) || null;\n    } catch (e) {\n      warn(\"[dsh-remote-ssh] settings.describe 失败，本次按空配置处理: \" + String(e && e.message ? e.message : e));\n      return null;\n    }\n  };\n  const valueOf = function () {\n    const form = formOf();\n    return form && form.value && typeof form.value === \"object\" ? form.value : null;\n  };\n  const write = async function (patch) {\n    const form = formOf();\n    await svc.update(entryId, patch, form ? form.revision : undefined);\n  };\n  let probed = false;\n  return {\n    formOf: formOf,\n    face: {\n      read: () => {\n        // 只 describe 一次：既用于读数，也用于（首次）形状探针\n        const form = formOf();\n        const v = form && form.value && typeof form.value === \"object\" ? form.value : nu