rkspaceId) === id) { victims.push(ws); continue; }\n      if (!ws.mirrorPath) continue;\n      try {\n        const entity = await workspaceRegistry.resolveByPath(ws.mirrorPath);\n        if (entity && String(entity.id) === id) victims.push(ws);\n      } catch (e) {}\n    }\n    if (!victims.length) return 0;\n    const rest = all.filter((w) => victims.indexOf(w) < 0);\n    try { await settingsFace.updateWorkspaces(rest); } catch (e) { return 0; }\n    for (const v of victims) {\n      if (!v.mirrorPath) continue;\n      try { await rm(v.mirrorPath, { recursive: true, force: true }); } catch (e) {}\n    }\n    try { ctx.logger?.info?.(\"[dsh-remote-ssh] 壳层删除工作区 → 同步移除设置条目 \" + victims.length + \" 条\"); } catch (e) {}\n    return victims.length;\n  }\n\n  /**\n   * 挂上「原生工作区删除」联动（issue #32）。壳层的「删除工作区」最终走\n   * `workspaceRegistry.delete(id)`（dsh-api-workspace-controller 的 delete 处理器），\n   * 我们包一层：原生删除成功后清掉设置里对应条目 + 镜像目录。\n   * 只包一次；服务对象不可写时静默放弃 —— 功能退化成「需要手动删条目」，不影响其它能力。\n   */\n  function installNativeDeleteSync() {\n    if (!workspaceRegistry || typeof workspaceRegistry.delete !== \"function\") return;\n    if (workspaceRegistry.__dshRemoteSshDeleteSync) return;\n    try {\n      const original = workspaceRegistry.delete.bind(workspaceRegistry);\n      const patched = async function (id) {\n        const result = await original(id);\n        try { await pruneWorkspaceEntriesForNativeId(id); } catch (e) {}\n        return result;\n      };\n      workspaceRegistry.delete = patched;\n      workspaceRegistry.__dshRemoteSshDeleteSync = true;\n      try { ctx.logger?.info?.(\"[dsh-remote-ssh] 已挂接原生工作区删除联动（壳层删区会同步删除设置条目）\"); } catch (e0) {}\n    } catch (e) {\n      try { ctx.logger?.warn?.(\"[dsh-remote-ssh] 无法挂接原生工作区删除联动（删除工作区后需手动删条目）: \" + String(e && e.message ? e.message : e)); } catch (e2) {}\n    }\n  }\n\n  const api = {\n    listProfiles: async () => ({ ok: true, profiles: publicProfiles(settingsFace.read().profiles) }),\n    /** 读取本机 ~/.ssh/config 发现的主机（借鉴 Yan-Ze